import React, { useEffect, useRef, useState, useCallback } from 'react';
import * as THREE from 'three';
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader';
import { useNavigate } from 'react-router-dom';
import { CanvasCapture } from 'canvas-capture';
import './CreateCharacter.css';

const GlbTest = () => {
  // ... (previous state and ref declarations remain the same)

  useEffect(() => {
    if (!canvasRef.current) return;

    const initThreeJS = () => {
      sceneRef.current = new THREE.Scene();
      sceneRef.current.background = null;
      cameraRef.current = new THREE.PerspectiveCamera(75, 1, 0.1, 1000);

      rendererRef.current = new THREE.WebGLRenderer({ 
        antialias: true, 
        canvas: canvasRef.current, 
        alpha: true,
        preserveDrawingBuffer: true 
      });
      rendererRef.current.setSize(400, 400);
      rendererRef.current.setClearColor(0x000000, 0);

      hiddenRendererRef.current = new THREE.WebGLRenderer({ 
        antialias: true, 
        canvas: hiddenCanvasRef.current, 
        alpha: true,
        preserveDrawingBuffer: true 
      });
      hiddenRendererRef.current.setSize(360, 640);
      hiddenRendererRef.current.setClearColor(0x000000, 0);

      // ... (rest of the initThreeJS function remains the same)
    };

    // ... (rest of the useEffect remains the same)
  }, [loadModel, updateCameraView]);

  const startRecording = () => {
    resetAndStartAnimation();

    const canvas = document.createElement('canvas');
    canvas.width = 400;
    canvas.height = 400;
    const ctx = canvas.getContext('2d');

    CanvasCapture.init(canvas, { verbose: true });
    CanvasCapture.beginGIFRecord({
      fps: 30,
      quality: 10,
      width: 400,
      height: 400,
      transparent: true
    });

    const duration = 3;
    const startTime = performance.now();

    const recordFrame = () => {
      const now = performance.now();
      const elapsed = (now - startTime) / 1000;

      if (elapsed < duration) {
        const delta = clockRef.current.getDelta();
        modelsRef.current.forEach(({ mixer }) => {
          if (mixer) mixer.update(delta);
        });

        hiddenRendererRef.current.clear();
        hiddenRendererRef.current.render(sceneRef.current, cameraRef.current);

        ctx.clearRect(0, 0, canvas.width, canvas.height);
        ctx.drawImage(hiddenCanvasRef.current, 0, 0);

        CanvasCapture.recordFrame();

        requestAnimationFrame(recordFrame);
      } else {
        CanvasCapture.stopRecord().then(gifBlob => {
          setGifBlob(gifBlob);

          // GIF download and upload logic remains the same
          // ...
        });
      }
    };

    recordFrame();
  };

  // ... (rest of the component remains the same)
};

export default GlbTest;
